/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnsremessasWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'REMCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remCodigo1.FromString(&GridStateDynamicFilter.Value) If not &remCodigo1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Código", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &remCodigo1 EndIf Case &DynamicFiltersSelector1 = !'REMCADASTRO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remCadastro1.FromString(&GridStateDynamicFilter.Value) &remCadastro_To1.FromString(&GridStateDynamicFilter.ValueTo) If not &remCadastro1.IsEmpty() OR not &remCadastro_To1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Mês e Ano", "WWP_FilterRange") &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Text = " - " EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &remCadastro1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &remCadastro_To1 EndIf Case &DynamicFiltersSelector1 = !'REMSTATUS' &remStatus1.FromString(&GridStateDynamicFilter.Value) If not &remStatus1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = "Status" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' do Case Case &remStatus1.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Ativo"
Case &remStatus1.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Inativo"
EndCase EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'REMCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remCodigo2.FromString(&GridStateDynamicFilter.Value) If not &remCodigo2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Código", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &remCodigo2 EndIf Case &DynamicFiltersSelector2 = !'REMCADASTRO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remCadastro2.FromString(&GridStateDynamicFilter.Value) &remCadastro_To2.FromString(&GridStateDynamicFilter.ValueTo) If not &remCadastro2.IsEmpty() OR not &remCadastro_To2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Mês e Ano", "WWP_FilterRange") &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Text = " - " EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &remCadastro2 &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &remCadastro_To2 EndIf Case &DynamicFiltersSelector2 = !'REMSTATUS' &remStatus2.FromString(&GridStateDynamicFilter.Value) If not &remStatus2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = "Status" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' do Case Case &remStatus2.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Ativo"
Case &remStatus2.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Inativo"
EndCase EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'REMCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remCodigo3.FromString(&GridStateDynamicFilter.Value) If not &remCodigo3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Código", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &remCodigo3 EndIf Case &DynamicFiltersSelector3 = !'REMCADASTRO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remCadastro3.FromString(&GridStateDynamicFilter.Value) &remCadastro_To3.FromString(&GridStateDynamicFilter.ValueTo) If not &remCadastro3.IsEmpty() OR not &remCadastro_To3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Mês e Ano", "WWP_FilterRange") &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Text = " - " EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &remCadastro3 &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &remCadastro_To3 EndIf Case &DynamicFiltersSelector3 = !'REMSTATUS' &remStatus3.FromString(&GridStateDynamicFilter.Value) If not &remStatus3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = "Status" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' do Case Case &remStatus3.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Ativo"
Case &remStatus3.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Inativo"
EndCase EndIf EndCase EndIf EndIf EndIf If not (&TFremCodigo.IsEmpty() AND &TFremCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Código") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFremCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFremCodigo_To EndIf If not (&TFremCadastro.IsEmpty() AND &TFremCadastro_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Mês e Ano") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &TFremCadastro WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &TFremCadastro_To EndIf If not (&TFremPeriodo1_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 1") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo1_Sel) Else If not (&TFremPeriodo1.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 1") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo1) EndIf EndIf If not (&TFremPeriodo2_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 2") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo2_Sel) Else If not (&TFremPeriodo2.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 2") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo2) EndIf EndIf If not (&TFremPeriodo3_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 3") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo3_Sel) Else If not (&TFremPeriodo3.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 3") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo3) EndIf EndIf If not (&TFremPeriodo4_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 4") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo4_Sel) Else If not (&TFremPeriodo4.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 4") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo4) EndIf EndIf If not (&TFremPeriodo5_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 5") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo5_Sel) Else If not (&TFremPeriodo5.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Período 5") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremPeriodo5) EndIf EndIf If not (&TFremStatus_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Status") &i = 1 For &TFremStatus_Sel in &TFremStatus_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf do Case Case &TFremStatus_Sel.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Ativo"
Case &TFremStatus_Sel.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Inativo"
EndCase &i += 1 EndFor EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Cells(&CellRow, &FirstColumn + 0).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 0).Color = 11 &ExcelDocument.Cells(&CellRow, &FirstColumn + 0).Text = "Código" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Color = 11 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Mês e Ano" &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Color = 11 &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Text = "Período 1" &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Color = 11 &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Text = "Período 2" &ExcelDocument.Cells(&CellRow, &FirstColumn + 4).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 4).Color = 11 &ExcelDocument.Cells(&CellRow, &FirstColumn + 4).Text = "Período 3" &ExcelDocument.Cells(&CellRow, &FirstColumn + 5).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 5).Color = 11 &ExcelDocument.Cells(&CellRow, &FirstColumn + 5).Text = "Período 4" &ExcelDocument.Cells(&CellRow, &FirstColumn + 6).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 6).Color = 11 &ExcelDocument.Cells(&CellRow, &FirstColumn + 6).Text = "Período 5" &ExcelDocument.Cells(&CellRow, &FirstColumn + 7).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 7).Color = 11 &ExcelDocument.Cells(&CellRow, &FirstColumn + 7).Text = "Status"
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsremessas order remStatus when &OrderedBy = 1 AND &OrderedDsc = False order (remStatus) when &OrderedBy = 1 AND &OrderedDsc = True order remCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (remCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order remCadastro when &OrderedBy = 3 AND &OrderedDsc = False order (remCadastro) when &OrderedBy = 3 AND &OrderedDsc = True
using trnsremessasWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &remCodigo1, &remCadastro1, &remCadastro_To1, &remStatus1 , &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &remCodigo2, &remCadastro2, &remCadastro_To2 , &remStatus2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &remCodigo3, &remCadastro3 , &remCadastro_To3, &remStatus3, &TFremCodigo, &TFremCodigo_To, &TFremCadastro, &TFremCadastro_To , &TFremPeriodo1, &TFremPeriodo1_Sel, &TFremPeriodo2, &TFremPeriodo2_Sel, &TFremPeriodo3, &TFremPeriodo3_Sel , &TFremPeriodo4, &TFremPeriodo4_Sel, &TFremPeriodo5, &TFremPeriodo5_Sel, &TFremStatus_Sels) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &ExcelDocument.Cells(&CellRow, &FirstColumn + 0).Number = remCodigo &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = remCadastro &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Text = WWP_Export_SecureText(remPeriodo1) &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Text = WWP_Export_SecureText(remPeriodo2) &ExcelDocument.Cells(&CellRow, &FirstColumn + 4).Text = WWP_Export_SecureText(remPeriodo3) &ExcelDocument.Cells(&CellRow, &FirstColumn + 5).Text = WWP_Export_SecureText(remPeriodo4) &ExcelDocument.Cells(&CellRow, &FirstColumn + 6).Text = WWP_Export_SecureText(remPeriodo5) &ExcelDocument.Cells(&CellRow, &FirstColumn + 7).Text = '' do Case Case remStatus.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 7).Text = "Ativo"
Case remStatus.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 7).Text = "Inativo"
EndCase
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnsremessasWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsremessasWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsremessasWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsremessasWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFREMCODIGO" &TFremCodigo.FromString(&GridStateFilterValue.Value) &TFremCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMCADASTRO" &TFremCadastro.FromString(&GridStateFilterValue.Value) &TFremCadastro_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMPERIODO1" &TFremPeriodo1.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO1_SEL" &TFremPeriodo1_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO2" &TFremPeriodo2.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO2_SEL" &TFremPeriodo2_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO3" &TFremPeriodo3.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO3_SEL" &TFremPeriodo3_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO4" &TFremPeriodo4.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO4_SEL" &TFremPeriodo4_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO5" &TFremPeriodo5.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO5_SEL" &TFremPeriodo5_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMSTATUS_SEL" &TFremStatus_SelsJson = &GridStateFilterValue.Value &TFremStatus_Sels.FromJson(&TFremStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforeWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

